function shareToHub_(file) {
  try {
    const me = String(Session.getEffectiveUser().getEmail() || '').toLowerCase();
    const owner = SpreadsheetApp.getActive().getOwner();
    const who = [WD.EMAIL, owner && owner.getEmail()].filter(Boolean).map(x => String(x).toLowerCase()).filter((x, i, a) => x !== me && a.indexOf(x) === i);
    if (who.length) file.addViewers(who);
  } catch (e) {
    console.warn('share attachment: ' + e);
    try { file.setSharing(DriveApp.Access.ANYONE_WITH_LINK, DriveApp.Permission.VIEW); } catch (e2) { console.warn('share link: ' + e2); }
  }
}

